        return "unknown"
    status = model_data.get("status", "unknown")
    if isinstance(status, str) and status.strip():
        return status
    return "unknown"


def _normalize_model_record(record):
    if not isinstance(record, dict):
        return None
    model_id = _extract_model_id(record)
    model_name = None
    for k in ("modelName", "model_name", "name", "modelNameSlug", "slug"):
        v = record.get(k)
        if isinstance(v, str) and v.strip():
            model_name = v
            break
    if not model_name:
        for k in ("servedModelName", "served_model_name", "gatewayModelId", "gateway_model_id"):
            v = record.get(k)
            if isinstance(v, str) and v.strip():
                model_name = v
                break
    model_path = None
    for k in ("modelPath", "model_path", "modelSourceId", "model_source_id"):
        v = record.get(k)
        if isinstance(v, str) and v.strip():
            model_path = v
            break
    status = _extract_status(record)
    return {
        "id": model_id,
        "name": model_name,
        "path": model_path,
        "status": status,
        "raw": record,
    }


def _iter_candidate_lists(payload):
    if isinstance(payload, list):
        yield payload
        return
    if not isinstance(payload, dict):
        return
    for key in (
        "items",
        "models",
        "data",
        "results",
        "content",
        "rows",
        "records",
    ):
        value = payload.get(key)
        if isinstance(value, list):
            yield value
    for outer_key in ("page", "result", "response"):
        outer_val = payload.get(outer_key)
        if isinstance(outer_val, dict):
            for inner_key in (
                "items",
                "models",
                "data",
                "results",
                "content",
                "rows",
                "records",
            ):
                inner_val = outer_val.get(inner_key)
                if isinstance(inner_val, list):
                    yield inner_val


def check_api_key_auth():
    if not TENSORMESH_API_KEY:
        return None

    profile_endpoints = [
        f"{CONTROL_PLANE_BASE}/auth/profile",
        f"{CONTROL_PLANE_BASE}/v1/auth/profile",
        f"{CONTROL_PLANE_BASE}/auth/me",
        f"{CONTROL_PLANE_BASE}/v1/me",
    ]

    auth_headers_variants = [
        {"Authorization": f"Bearer {TENSORMESH_API_KEY}"},
        {"Authorization": f"Api-Key {TENSORMESH_API_KEY}"},
        {"X-API-Key": TENSORMESH_API_KEY},
        {"Authorization": f"Token {TENSORMESH_API_KEY}"},
    ]

    for endpoint in profile_endpoints:
        for auth_headers in auth_headers_variants:
            headers = {**auth_headers, "Content-Type": "application/json"}
            try:
                resp = requests.get(endpoint, headers=headers, timeout=15)
                if resp.status_code == 200:
                    print(
                        f"  Auth succeeded: {endpoint} with {list(auth_headers.keys())[0]}",
                        flush=True,
