def list_models(token, page_size=100):
    headers = {
        "Authorization": f"Bearer {token}",
        "Content-Type": "application/json",
    }
    urls = [
        f"{CONTROL_PLANE_BASE}/v1/models?size={page_size}",
        f"{CONTROL_PLANE_BASE}/v1/models?page=1&size={page_size}",
        f"{CONTROL_PLANE_BASE}/v1/models",
    ]
    collected = []
    seen_ids = set()
    seen_keys = set()
    for url in urls:
        try:
            resp = requests.get(url, headers=headers, timeout=60)
        except Exception:
            continue
        if resp.status_code != 200:
            continue
        try:
            payload = resp.json()
        except Exception:
            continue
        found_any = False
        for items in _iter_candidate_lists(payload):
            for item in items:
                normalized = _normalize_model_record(item)
                if not normalized:
                    continue
                identity = normalized.get("id") or f"{normalized.get('name')}::{normalized.get('path')}"
                if identity in seen_ids:
                    continue
                seen_ids.add(identity)
                found_any = True
                collected.append(normalized)
        if found_any:
            return collected
        if isinstance(payload, dict):
            normalized = _normalize_model_record(payload)
            if normalized and normalized.get("id"):
                key = normalized.get("id")
                if key not in seen_keys:
                    seen_keys.add(key)
                    collected.append(normalized)
                    return collected
    return collected


def find_existing_model(token, target_name=None, target_path=None):
    target_name = (target_name or MODEL_SLUG).strip().lower()
    target_path = (target_path or MODEL_NAME).strip().lower()
    models = list_models(token)
    exact_name_matches = []
    exact_path_matches = []
    fuzzy_matches = []
    for item in models:
        name = (item.get("name") or "").strip().lower()
        path = (item.get("path") or "").strip().lower()
        if name == target_name:
            exact_name_matches.append(item)
        if path == target_path:
            exact_path_matches.append(item)
        if MODEL_SLUG.lower() in name or MODEL_NAME.lower() in path:
            fuzzy_matches.append(item)
    for bucket in (exact_name_matches, exact_path_matches, fuzzy_matches):
        if bucket:
            preferred = sorted(
                bucket,
                key=lambda x: (
                    0
                    if str(x.get("status", "")).lower() in ("active", "running", "served", "ready")
                    else 1,
                    0 if x.get("id") else 1,
                ),
            )[0]
            return preferred
    return None


