                "region": REGION,
                "gpu_type": GPU_TYPE,
                "gpu_count": GPU_COUNT,
                "replicas": REPLICAS,
                "scaling_mode": "fixed",
                "cpu_offloading": True,
            },
            "vllm_config": {
                "extra_args": ["--trust-remote-code"],
            },
        },
    ]

    last_resp = None

    for i, payload in enumerate(payloads_to_try, 1):
        _log(f"Deploy attempt {i}/{len(payloads_to_try)}...")
        _log(f"Payload: {json.dumps(payload, indent=2)}")
        resp = requests.post(url, headers=headers, json=payload, timeout=120)
        last_resp = resp
        if resp.status_code in (200, 201):
            _log(f"Attempt {i} succeeded!")
            return resp
        if resp.status_code == 409:
            _log(f"Attempt {i} reported existing model ({resp.status_code}): {resp.text}")
            existing = find_existing_model(token, payload.get("model_name"), payload.get("model_path"))
            if existing and existing.get("id"):
                existing_id = existing["id"]
                _log(f"Reusing existing model with ID: {existing_id}")
                existing_status = get_model_status(token, existing_id)
                if existing_status is not None:
                    class ExistingModelResponse:
                        def __init__(self, data):
                            self.status_code = 200
                            self._data = data
                            self.text = _safe_json(data)

                        def json(self):
                            return self._data

                    return ExistingModelResponse(existing_status)
                class ExistingModelFallbackResponse:
                    def __init__(self, data):
                        self.status_code = 200
                        self._data = data
                        self.text = _safe_json(data)

                    def json(self):
                        return self._data

                return ExistingModelFallbackResponse(existing["raw"])
        _log(f"Attempt {i} failed ({resp.status_code}): {resp.text}")

    return last_resp


def verify_inference(token, gateway_base, user_id, served_model_name):
    test_url = f"{gateway_base}/v1/chat/completions"
    test_headers = {
        "Authorization": f"Bearer {token}",
        "X-User-Id": user_id,
        "Content-Type": "application/json",
    }
    test_data = {
        "model": served_model_name,
        "messages": [
            {
                "role": "user",
                "content": "Hello! Please respond with a short greeting.",
            }
        ],
        "max_tokens": 100,
    }
    try:
        test_resp = requests.post(
            test_url, headers=test_headers, json=test_data, timeout=120
        )
        if test_resp.status_code == 200:
            test_result = test_resp.json()
            content = ""
            if isinstance(test_result, dict):
                choices = test_result.get("choices")
                if isinstance(choices, list) and choices:
                    msg = choices[0].get("message", {})
                    if isinstance(msg, dict):
                        content = msg.get("content", "") or ""
            _log(f"Model test response: {content}")
            return True
        _log(
            f"Test request returned status {test_resp.status_code}: {test_resp.text}"
        )
        return False
    except Exception as e:
        _log(f"Test request failed: {e}")
        return False


