        _log(f"ERROR: Could not parse deployment response: {e}")
        _log(f"Raw response: {getattr(resp, 'text', '')}")
        auth_state["deployment_error"] = f"JSON parse error: {e}"
        auth_state["deployment_done"] = True
        return

    auth_state["deployment_result"] = deploy_result

    _log("Deployment initiated!")
    _log(f"Response: {json.dumps(deploy_result, indent=2)}")

    model_id = _extract_model_id(deploy_result)

    if not model_id:
        existing = find_existing_model(token, MODEL_SLUG, MODEL_NAME)
        if existing and existing.get("id"):
            model_id = existing["id"]

    if not model_id:
