        auth_state["deployment_error"] = "No model ID in response"
        auth_state["deployment_done"] = True
        return

    auth_state["model_id"] = model_id

    _log(f"")
    _log(f"Model ID: {model_id}")
    _log("Waiting for deployment to become active...")
    _log("(Gemma 4 31B on H200 with latest transformers may take 10-25 minutes)")
    _log("")

    timeout_seconds = 3600
    poll_interval = 20
