        _log(f"  [{int(time.time() - start)}s] Status: {status}")

        if isinstance(status, str) and status.lower() in (
            "active",
            "running",
            "served",
            "ready",
        ):
            served_model_name = _extract_served_model_name(status_data)
            gateway_base = (
                _extract_gateway_base(status_data)
                or ""
            )
            user_id = _extract_user_id(profile) or "unknown"

            auth_state["served_model_name"] = served_model_name
            auth_state["gateway_base"] = gateway_base
            auth_state["user_id"] = user_id

            _log("")
            _log("=" * 60)
            _log("DEPLOYMENT IS ACTIVE!")
            _log("=" * 60)
            _log(f"")
            _log(f"Model ID: {model_id}")
            _log(f"Served Model Name: {served_model_name}")
            _log(f"Gateway Base URL: {gateway_base}")
            _log(f"User ID (X-User-Id): {user_id}")
            _log(f"API Key: {token[:8]}{'*' * 20}")
            _log("")
            _log("cURL example:")
            _log(
                f"curl -sS \\\n  -H \"Authorization: Bearer {token}\" \\\n  -H \"X-User-Id: {user_id}\" \\\n  -H \"Content-Type: application/json\" \\\n  \"{gateway_base}/v1/chat/completions\" \\\n  -d '{{\"model\": \"{served_model_name}\", \"messages\": [{{\"role\": \"user\", \"content\": \"Hello!\"}}]}}'"
            )
            _log("")
            _log("=" * 60)

            _log("")
            _log("Sending test request to verify model is responding...")
            verify_inference(token, gateway_base, user_id, served_model_name)

            auth_state["deployment_done"] = True
            auth_state["deployment_error"] = None
            return

        if isinstance(status, str) and status.lower() in (
            "error",
            "failed",
            "deleted",
            "terminated",
        ):
            _log(f"")
            _log(f"Deployment entered terminal state: {status}")
            _log(f"Details: {json.dumps(status_data, indent=2)}")
            auth_state["deployment_error"] = f"Terminal state: {status}"
            auth_state["deployment_done"] = True
            return

        time.sleep(poll_interval)

    _log(f"")
    _log(f"Timeout after {timeout_seconds}s waiting for deployment.")
    auth_state["deployment_error"] = f"Timeout after {timeout_seconds}s"
    auth_state["deployment_done"] = True


