def _extract_status(model_data):
    candidates = []
    visited = set()

    def walk(node):
        node_id = id(node)
        if node_id in visited:
            return
        visited.add(node_id)
        if isinstance(node, dict):
            for key in (
                "status",
                "state",
                "phase",
                "deploymentStatus",
                "deployment_status",
                "servedStatus",
                "served_status",
                "modelStatus",
                "model_status",
                "runtimeStatus",
                "runtime_status",
                "health",
            ):
                value = node.get(key)
                if isinstance(value, str) and value.strip():
                    candidates.append(value.strip())
            for value in node.values():
                if isinstance(value, (dict, list)):
                    walk(value)
        elif isinstance(node, list):
            for item in node:
                if isinstance(item, (dict, list)):
                    walk(item)

    walk(model_data)

    priority = [
        "active",
        "running",
        "ready",
        "served",
        "success",
        "succeeded",
        "deploying",
        "provisioning",
        "creating",
        "pending",
        "initializing",
        "queued",
        "processing",
        "unknown",
        "error",
        "failed",
        "terminated",
        "deleted",
    ]
    lowered = [candidate.lower() for candidate in candidates]
    for wanted in priority:
        for index, candidate in enumerate(lowered):
            if candidate == wanted:
                return candidates[index]
    if candidates:
        return candidates[0]
    return "unknown"


def _iter_candidate_lists(payload):
    if isinstance(payload, list):
        yield payload
        return
    if not isinstance(payload, dict):
        return
    for key in ("items", "models", "data", "results", "content", "rows", "records"):
        value = payload.get(key)
        if isinstance(value, list):
            yield value
    for outer_key in ("page", "result", "response"):
        outer_value = payload.get(outer_key)
        if isinstance(outer_value, dict):
            for inner_key in ("items", "models", "data", "results", "content", "rows", "records"):
                inner_value = outer_value.get(inner_key)
                if isinstance(inner_value, list):
