    auth_state["gateway_base"] = gateway_base
    auth_state["user_id"] = user_id
    auth_state["gateway_api_key"] = gateway_api_key
    auth_state["deployment_done"] = True
    auth_state["deployment_error"] = None


def deployment_worker(token):
    global _deployment_started
    with _deployment_lock:
        if _deployment_started:
            return
        _deployment_started = True

    _log("")
    _log("=" * 60)
    _log("STARTING DEPLOYMENT")
    _log(f"Model: {MODEL_NAME}")
    _log(f"GPU: {GPU_COUNT}x {GPU_TYPE}")
    _log(f"Provider: {CLOUD_PROVIDER} / {REGION}")
    _log("=" * 60)
    _log("")

    profile = get_user_profile(token)
    if profile:
        _log(f"Authenticated as: {_extract_display_name(profile)}")
    else:
        _log("WARNING: Could not verify user profile, proceeding with deployment...")

    _log("")
    _log("Sending deployment request...")

    try:
        resp = deploy_model_with_token(token)
    except Exception as e:
        _log(f"ERROR: Deployment request exception: {e}")
        auth_state["deployment_error"] = str(e)
        auth_state["deployment_done"] = True
        return

    if resp is None or resp.status_code not in (200, 201):
        status_code = getattr(resp, "status_code", "unknown")
        text = getattr(resp, "text", "")
        _log(f"ERROR: Deployment failed. Status: {status_code}")
        _log(f"Response: {text}")
        auth_state["deployment_error"] = f"HTTP {status_code}: {text}"
        auth_state["deployment_done"] = True
        return

    try:
        deploy_result = resp.json()
    except Exception as e:
        _log(f"ERROR: Could not parse deployment response: {e}")
        _log(f"Raw response: {getattr(resp, 'text', '')}")
        auth_state["deployment_error"] = f"JSON parse error: {e}"
        auth_state["deployment_done"] = True
        return

    auth_state["deployment_result"] = deploy_result
    _log("Deployment initiated!")
    _log(f"Response: {json.dumps(deploy_result, indent=2)}")

    model_id = _extract_model_id(deploy_result)
    if not model_id:
        existing = find_existing_model(token, MODEL_SLUG, MODEL_NAME)
        if existing and existing.get("id"):
            model_id = existing["id"]

    if not model_id:
        _log("ERROR: Could not extract model ID from deployment response.")
        auth_state["deployment_error"] = "No model ID in response"
        auth_state["deployment_done"] = True
        return

    auth_state["model_id"] = model_id
    _log("")
    _log(f"Model ID: {model_id}")
    _log("Waiting for deployment to become active...")
    _log("(Gemma 4 31B on H200 with latest transformers may take 10-25 minutes)")
    _log("")

    timeout_seconds = 3600
    poll_interval = 20
    start = time.time()
    profile_user_id = _extract_user_id(profile)
    deploy_gateway_base = _extract_gateway_base(deploy_result) or DEFAULT_GATEWAY_BASE
    deploy_served_name = _extract_served_model_name(deploy_result) or MODEL_SLUG
    deploy_gateway_api_key = _extract_gateway_api_key(deploy_result)

    while time.time() - start < timeout_seconds:
        elapsed = int(time.time() - start)
        status_data = get_model_status(token, model_id)
        if status_data is None:
            _log(f"  [{elapsed}s] Failed to fetch status, retrying...")
            time.sleep(poll_interval)
            continue

        status = _extract_status(status_data)
        auth_state["last_status"] = status
        _log(f"  [{elapsed}s] Status: {status}")

        served_model_name = _extract_served_model_name(status_data) or deploy_served_name or MODEL_SLUG
        gateway_base = _extract_gateway_base(status_data) or deploy_gateway_base or DEFAULT_GATEWAY_BASE
        gateway_api_key = _extract_gateway_api_key(status_data) or deploy_gateway_api_key or token
        user_id = profile_user_id or _extract_user_id(status_data) or "unknown"

        auth_state["served_model_name"] = served_model_name
        auth_state["gateway_base"] = gateway_base
        auth_state["user_id"] = user_id
        auth_state["gateway_api_key"] = gateway_api_key

        lowered_status = str(status).lower().strip()
        if lowered_status in ("active", "running", "served", "ready", "success", "succeeded"):
            _log("")
            _log("=" * 60)
            _log("DEPLOYMENT IS ACTIVE!")
            _log("=" * 60)
            _log("")
            _log(f"Model ID: {model_id}")
            _log(f"Served Model Name: {served_model_name}")
            _log(f"Gateway Base URL: {gateway_base}")
            _log(f"User ID (X-User-Id): {user_id}")
            _log(f"API Key: {_mask_token(gateway_api_key)}")
            _log("")
            _log("cURL example:")
            _log(
                f"curl -sS \\\n  -H \"Authorization: Bearer {gateway_api_key}\" \\\n  -H \"X-User-Id: {user_id}\" \\\n  -H \"Content-Type: application/json\" \\\n  \"{gateway_base}/v1/chat/completions\" \\\n  -d '{{\"model\": \"{served_model_name}\", \"messages\": [{{\"role\": \"user\", \"content\": \"Hello!\"}}]}}'"
            )
            _log("")
            _log("=" * 60)
            _log("")
            _log("Sending test request to verify model is responding...")
            ok, detail = verify_inference(gateway_api_key, gateway_base, user_id, served_model_name)
            if ok:
                _log(f"Model test response: {detail}")
            else:
                _log(f"Test request failed: {detail}")
            _start_success_state(model_id, served_model_name, gateway_base, user_id, gateway_api_key)
            return

        if lowered_status in ("error", "failed", "deleted", "terminated"):
            _log("")
            _log(f"Deployment entered terminal state: {status}")
            _log(f"Details: {json.dumps(status_data, indent=2)}")
            auth_state["deployment_error"] = f"Terminal state: {status}"
            auth_state["deployment_done"] = True
            return

        if lowered_status == "unknown" and elapsed >= 120:
            logs_payload = get_model_logs(token, model_id, limit=100)
            if logs_payload is not None:
                _log(f"  [{elapsed}s] Retrieved deployment logs for fallback diagnosis.")
                readiness = _logs_indicate_ready(logs_payload)
                if readiness is True:
                    _log(f"  [{elapsed}s] Logs indicate deployment is likely ready; attempting inference probe.")
                    ok, detail = verify_inference(gateway_api_key, gateway_base, user_id, served_model_name)
                    if ok:
                        _log(f"Model test response: {detail}")
                        _log("")
                        _log("=" * 60)
                        _log("DEPLOYMENT IS ACTIVE!")
                        _log("=" * 60)
                        _log("")
                        _log(f"Model ID: {model_id}")
                        _log(f"Served Model Name: {served_model_name}")
                        _log(f"Gateway Base URL: {gateway_base}")
                        _log(f"User ID (X-User-Id): {user_id}")
                        _log(f"API Key: {_mask_token(gateway_api_key)}")
                        _start_success_state(model_id, served_model_name, gateway_base, user_id, gateway_api_key)
                        return
                    _log(f"  [{elapsed}s] Inference probe not ready yet: {detail}")
                elif readiness is False:
                    _log(f"  [{elapsed}s] Logs indicate an error condition.")
                    _log(_safe_json(logs_payload))
                    auth_state["deployment_error"] = "Deployment logs indicate an error condition"
                    auth_state["deployment_done"] = True
                    return
            else:
                _log(f"  [{elapsed}s] No deployment logs available yet.")

        time.sleep(poll_interval)

    _log("")
    _log(f"Timeout after {timeout_seconds}s waiting for deployment.")
    auth_state["deployment_error"] = f"Timeout after {timeout_seconds}s"
    auth_state["deployment_done"] = True


